def table(df):
 cols=list(df.columns);lines=['|'+'|'.join(cols)+'|','|'+'|'.join(['---']*len(cols))+'|']
 for row in df.itertuples(index=False,name=None):lines.append('|'+'|'.join('NOT_ARCHIVED' if pd.isna(v) else format(v,'.17g') if isinstance(v,float) else str(v).replace('|','/') for v in row)+'|')
 return '\n'.join(lines)
